/// <summary>
/// M.essl 11.03.2024
/// </summary>
/// <param name = "_assignOriginInfoToLoadTable">AMDeviceId</param>
/// <param name = "_assignTransTemplateToLoadTable">AMDeviceId</param>
/// <param name = "_assignEarliestSchedShipDateTime">AMDeviceId</param>
public void insert(
    boolean _assignOriginInfoToLoadTable,
    boolean _assignTransTemplateToLoadTable,
    boolean _assignEarliestSchedShipDateTime)
{
    next insert(_assignOriginInfoToLoadTable, _assignTransTemplateToLoadTable, _assignEarliestSchedShipDateTime);

    AVASplitShipConfirmUpdateContainerDisposal instance = AVASplitShipConfirmUpdateContainerDisposal::current();

    if (instance 
     && instance.newLoadLineRecIds
     && instance.lastUpdatedLoadLineRecId
     && instance.existsLoadLineRec(instance.lastUpdatedLoadLineRecId))
    {
        instance.insertLoadLineRec(instance.lastUpdatedLoadLineRecId,this.RecId);
        instance.lastUpdatedLoadLineRecId = 0;
    }
}

public void update(boolean _isConsolidation, boolean _updateScheduledShipDateTime)
{
    WHSLoadLine      origWHSLoadLine;

    origWHSLoadLine = this.orig();

    AVASplitShipConfirmUpdateContainerDisposal instance = AVASplitShipConfirmUpdateContainerDisposal::current();

    if (instance)
    {
        if (instance.loadId
         && instance.loadId != this.LoadId
         && origWHSLoadLine.LoadId != this.LoadId)
        {
            instance.insertLoadLineRec(this.RecId, this.RecId);
        }
        else if (this.InventQty != origWHSLoadLine.InventQty)
        {
            instance.insertLoadLineRec(this.RecId, this.RecId);
            instance.lastUpdatedLoadLineRecId = this.RecId;
        }
    }

    next update(_isConsolidation, _updateScheduledShipDateTime);


}
